import {adminFetch} from '../session-recovery.mjs';
import {createEditorDrafts} from './editor-drafts.mjs';
import {ruleDates,ruleLabel,occasionRule,MONTHS,WEEKDAYS,ORDINALS} from '../../src/seasons/date-rules.mjs';
import {occasionSummary,sortedOccasionSummaries,calendarAgenda,campaignLabels,readyConfirmation,manualActivationConfirmation,ICON_PRESETS,iconDefinition,saveIcon} from '../../src/seasons/occasion-summary.mjs';
import {prepareIcon} from './icon-upload.mjs';
import {enhanceSelects} from './select-menu.mjs';
import {STORE_KEY,PREF_KEY,OCCASIONS,ORIGINAL_COPY,occasion as baseOccasion,allOccasions,visibleOccasions,hasTheme,isThemeReady,readinessIssue,THEME_STAGES,themeProgress as getThemeProgress,setThemeProgress,previewCampaign,saveOccasion,removeOccasion,restoreOccasion,seedState,nowSAST,millis,localTime,formatDate,yearOf,instances,scheduledInstances,resolveAt,nextCampaign,statusOf,conflicts,validatePublish,validRange,cloneCampaign,addHistory} from '../../src/seasons/model.mjs';
const $=id=>document.getElementById(id),escape=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
let state=seedState(),view=new URLSearchParams(location.search).get('view')==='occasions'?'library':'calendar',month=nowSAST().slice(0,7),selectedDay='',selectedId=null,draft=null,tab='wording',device='desktop',previewMode='draft',page='/',showDrafts=false,toastTimer,frameObserver;
const editorDrafts=createEditorDrafts();
state.clock={simulated:false,at:nowSAST()};month=state.clock.at.slice(0,7);
const occasion=id=>baseOccasion(id,state);
const at=()=>state.clock.simulated?state.clock.at:nowSAST();
const btn=(text,action,cls='',extra='')=>`<button type="button" class="button ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const check=(id,label,detail,checked,disabled=false)=>`<label class="check"><input type="checkbox" id="${id}" ${checked?'checked':''} ${disabled?'disabled':''}><span><strong>${label}</strong><small>${detail}</small></span></label>`;
function notify(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500)}
let serverRevision=0,busy=false,loaded=false;
async function readRemote(){const r=await adminFetch('/api/seasons',{cache:'no-store'});if(!r.ok)throw Error('Could not load saved themes. Reload and sign in again.');return r.json()}
async function refreshRemote(){const clock=state.clock;state=await readRemote();serverRevision=state.revision;state.clock=clock||{simulated:false,at:nowSAST()};return state}
async function persist(action){
 if(!loaded)throw Error('Wait for settings to load.');
 if(!action){postPreview();return}
 busy=true;$('app').inert=true;$('connection-status').textContent='Saving…';
 try{const session=await adminFetch('/api/session',{cache:'no-store'});if(!session.ok)throw Error('Sign in again before saving.');const {csrf}=await session.json();
 const r=await adminFetch('/api/seasons',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({state:{...state,revision:serverRevision},action})});
 const result=await r.json();if(!r.ok)throw Error(result.error||'Could not save changes.');
 const clock=state.clock;state=result;state.clock=clock;serverRevision=result.revision;$('connection-status').textContent='Saved';postPreview();
 }catch(error){$('connection-status').textContent='Not saved';try{await refreshRemote()}catch{}throw error}
 finally{busy=false;$('app').inert=false}
}
async function perform(handler,e){if(busy||!loaded)return;try{await handler(e)}catch(error){render();notify(error.message||'Could not save. Please reload before trying again.')}}
function activeInfo(){return resolveAt(state,at())}
function preferred(oid){return occasionSummary(state,oid,at()).campaign}
function clockBar(){return `${state.clock.simulated?`<div class="simulation-banner" role="status"><div><strong>Preview only: ${formatDate(at())}</strong><span>The statuses below use this pretend date. Today is ${formatDate(nowSAST())}.</span></div>${btn('Return to today','real-clock','small')}</div>`:''}<details class="clock-bar"><summary>${state.clock.simulated?'Change preview date':'Preview a different date'}</summary><div class="clock-controls"><p>See what the website would look like on another date. Reloading returns to today.</p><label for="clock-at">Preview date</label><input type="datetime-local" id="clock-at" value="${at()}">${btn('Preview this date','apply-clock','small')}${['halloween','christmas'].filter(id=>!occasion(id).removed&&Number.isFinite(millis(preferred(id)?.start))).map(id=>btn('Preview '+escape(occasion(id).name),'jump-'+id,'small')).join('')}</div></details>`}

function statusStrip(){const a=activeInfo(),current=previewCampaign(state,a.campaign),next=sortedOccasionSummaries(state,at()).find(s=>s.kind==='upcoming');return `<div class="status-strip"><div><small>${state.clock.simulated?'SHOWING ON THE PREVIEW DATE':'SHOWING NOW ON YOUR WEBSITE'}</small><strong>${current?escape(occasion(current.occasion).name):'Original CustomVibe'}</strong><p>${current?(a.reason==='Manual override'?'Turned on manually':state.clock.simulated?'Active in preview':'Current scheduled theme'):state.mode==='off'?'Automatic starts are paused.':'No seasonal theme is showing.'}</p></div><div><small>${state.clock.simulated?'NEXT IN THIS PREVIEW':'NEXT THEME TO GO LIVE'}</small><strong>${next?escape(next.definition.name):'Nothing scheduled to go live'}</strong><p>${next?formatDate(next.start):'Set a date and enable a completed theme.'}</p></div><div class="status-actions">${btn('View as visitor','visitor','small')}${btn('Resume schedule','resume','small')}${btn('Stop all themes','stop','small danger')}</div></div>`}

function shell(content){return `<div class="page-heading"><div><h1>Themes & seasons</h1><p class="intro">One theme for each occasion. Plan it, preview it, make it yours.</p></div></div>${clockBar()}${statusStrip()}<nav class="page-tabs" aria-label="Seasonal views">${['overview','calendar','library','history'].map(v=>`<button data-action="view" data-view="${v}" ${view===v?'aria-current="page"':''}>${{overview:'Overview',calendar:'Calendar',library:'Occasions',history:'Change history'}[v]}</button>`).join('')}</nav>${content}<div class="demo-footer"><span>Schedule times use South African time. Date previews do not change the live clock.</span></div>`}
function labelsHTML(c){const labels=campaignLabels(state,c,at());return `<span class="occasion-labels"><span class="schedule-label ${labels.schedule==='Active'?'active':''}"><b>Schedule:</b> ${labels.schedule}</span><span class="theme-label"><b>Theme:</b> ${labels.theme}</span></span><span class="activation-detail ${labels.kind}">${escape(labels.detail)}</span>`}
function eventList(items){return `<ul class="event-list">${items.map(c=>`<li><button data-action="edit" data-id="${c.id}"><strong>${escape(occasion(c.occasion).name)}</strong>${labelsHTML(c)}<small>${formatDate(c.start)} to ${formatDate(c.end)}${c.repeat==='annual'?' · Every year':''}${c.dateRule?' · '+ruleLabel(c.dateRule):''}</small></button></li>`).join('')||'<li>No campaigns in this period.</li>'}</ul>`}
function renderOverview(){const rows=sortedOccasionSummaries(state,at()),ready=rows.filter(s=>s.kind==='upcoming'),attention=rows.filter(s=>['paused','attention'].includes(s.kind));return `<div class="section-heading"><div><h2>At a glance</h2><p>Check what is showing now above, then see what will go live next.</p></div></div><div class="upcoming-grid"><section><h3>Set to go live</h3>${ready.length?`<ul class="event-list">${ready.map(s=>`<li><button data-action="edit-schedule" data-id="${s.campaign.id}"><strong>${escape(s.definition.name)}</strong>${labelsHTML(s.campaign)}</button></li>`).join('')}</ul>`:'<p class="plain-note">No themes are set to go live.</p>'}${btn('Manage occasions','view','small','data-view="library"')}</section><section><h3>Needs your attention</h3>${attention.length?`<ul class="event-list">${attention.map(s=>`<li><button data-action="edit-schedule" data-id="${s.campaign.id}"><strong>${escape(s.definition.name)}</strong>${labelsHTML(s.campaign)}</button></li>`).join('')}</ul>`:'<p class="plain-note">No scheduled themes need attention.</p>'}<p class="plain-note">Unscheduled occasions stay in Occasions until you choose to use them.</p></section></div>`}

function calendarItems(){const y=Number(month.slice(0,4));const all=scheduledInstances(state,y-1,y+1);if(showDrafts)all.push(...state.campaigns.filter(c=>!occasion(c.occasion).removed&&(!c.published||!c.enabled||occasion(c.occasion).moving&&!c.dateRule&&!c.datesReviewed)).flatMap(c=>instances(c,y-1,y+1)));return all}
function iconHTML(icon){return icon.image?`<img src="${escape(icon.image)}" alt="">`:`<span aria-hidden="true">${icon.symbol}</span>`}
function occasionIcon(id){return iconHTML(iconDefinition(state,id))}
let iconId=null,iconChoice=null,iconBusy=false,iconLoad=0;
function iconDialog(){return `<dialog class="copy-dialog icon-dialog" id="icon-dialog" aria-labelledby="icon-title"><h2 id="icon-title">Change icon</h2><p>Used on the occasion card, calendar dates and legend.</p><div class="icon-preview" id="icon-preview" aria-label="Selected icon"></div><div class="icon-presets" aria-label="Choose an icon">${ICON_PRESETS.map(i=>btn(iconHTML(i),'choose-icon','icon-option',`data-icon="${i.id}" aria-label="${i.name}" aria-pressed="false"`)).join('')}</div><label class="icon-upload" for="icon-file">Upload your own image<input id="icon-file" type="file" accept="image/png,image/jpeg,image/webp"></label><p class="hint">PNG, JPG or WebP, up to 2 MB. Saved with this occasion and used throughout the calendar.</p><p id="icon-error" role="alert"></p><div class="actions">${btn('Reset icon','reset-icon','small')}${btn('Cancel','cancel-icon','small')}${btn('Save icon','save-icon','primary small','id="save-icon"')}</div></dialog>`}
function refreshIconChoice(){const selected=iconDefinition(state,iconId,iconChoice);$('icon-preview').innerHTML=iconHTML(selected);$('icon-preview').setAttribute('aria-label','Selected icon: '+selected.name);document.querySelectorAll('[data-icon]').forEach(b=>b.setAttribute('aria-pressed',String(selected.id===b.dataset.icon)));$('save-icon').disabled=iconBusy}

function renderMonth(y,m,items){const monthKey=`${y}-${String(m).padStart(2,'0')}`,days=new Date(Date.UTC(y,m,0)).getUTCDate(),offset=(new Date(Date.UTC(y,m-1,1)).getUTCDay()+6)%7,title=new Date(Date.UTC(y,m-1,1)).toLocaleDateString('en-ZA',{month:'long',timeZone:'UTC'});let cells=Array.from({length:offset},()=>'<div class="year-day empty" aria-hidden="true"></div>');for(let d=1;d<=days;d++){const date=monthKey+'-'+String(d).padStart(2,'0'),start=millis(date+'T00:00'),events=items.filter(c=>millis(c.start)<start+86400000&&millis(c.end)>start);cells.push(`<div class="year-day ${selectedDay===date?'selected':''} ${events.length?'has-occasion':''}"><button class="year-date" data-action="day" data-date="${date}" aria-label="Preview ${date}${events.length?', '+events.map(c=>occasion(c.occasion).name).join(', '):''}" ${selectedDay===date?'aria-pressed="true"':''}>${d}</button><div class="date-occasions">${events.map(c=>`<button class="date-icon ${!c.published||!c.enabled||!isThemeReady(state,c.occasion)?'draft':''}" data-action="edit" data-id="${c.id}" aria-label="Edit ${escape(occasion(c.occasion).name)} on ${date}" title="${escape(occasion(c.occasion).name)} · Schedule: ${campaignLabels(state,c,at()).schedule} · Theme: ${campaignLabels(state,c,at()).theme} · ${formatDate(c.start)} to ${formatDate(c.end)}">${occasionIcon(c.occasion)}</button>`).join('')}</div></div>`)}while(cells.length<42)cells.push('<div class="year-day empty" aria-hidden="true"></div>');return `<section class="year-month" aria-label="${title} ${y}"><h3>${title}</h3><div class="weekdays">${['M','T','W','T','F','S','S'].map((d,i)=>`<span aria-label="${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]}">${d}</span>`).join('')}</div><div class="days">${cells.join('')}</div></section>`}
function renderCalendar(){const agenda=calendarAgenda(state,at());const y=Number(month.slice(0,4)),items=calendarItems(),selected=selectedDay?items.filter(c=>millis(c.start)<millis(selectedDay+'T00:00')+86400000&&millis(c.end)>millis(selectedDay+'T00:00')):[],shown=visibleOccasions(state).filter(o=>items.some(c=>c.occasion===o.id&&millis(c.start)<millis((y+1)+'-01-01T00:00')&&millis(c.end)>millis(y+'-01-01T00:00')));return `<div class="year-toolbar"><div><h2>${y} at a glance</h2><p>Saved dates for the year. Faded icons cannot activate yet.</p></div><div class="year-navigation">${btn('‹','previous-year','small','aria-label="Previous year"')}<label for="calendar-year">Year</label><input type="number" id="calendar-year" aria-label="Calendar year" min="2026" max="2100" value="${y}">${btn('Show','show-year','small')}${btn('›','next-year','small','aria-label="Next year"')}</div></div><div class="year-legend">${shown.map(o=>`<span>${occasionIcon(o.id)} ${escape(o.name)}</span>`).join('')||'<span>No schedules this year.</span>'}<label class="cal-filter"><input type="checkbox" id="show-drafts" ${showDrafts?'checked':''}> Show drafts and disabled campaigns</label></div><div class="calendar-layout year-layout"><section class="year-grid" aria-label="Full year campaign calendar">${Array.from({length:12},(_,i)=>renderMonth(y,i+1,items)).join('')}</section><aside class="calendar-side"><h3>${selectedDay?formatDate(selectedDay+'T12:00').split(',')[0]:'Explore your year'}</h3><p>Select a date to preview midday. Select an occasion icon to edit its campaign. Exact start and end times still apply.</p>${selectedDay?eventList(selected):''}${btn('View this date as visitor','visitor-date','small')}<h3 style="margin-top:30px">Ready to go live</h3>${agenda.ready.length?eventList(agenda.ready.slice(0,3)):'<p>No approved themes are set to go live.</p>'}${agenda.blocked.length?'<h3 style="margin-top:30px">Blocked schedules</h3><p>These are saved dates only. They will not activate while blocked.</p>'+eventList(agenda.blocked.slice(0,3)):''}<p>Faded icons are drafts, disabled schedules or themes not yet Ready to use. Manual overrides and Stop all are shown in the status above.</p></aside></div>`}

function themeProgress(oid){return getThemeProgress(state,oid)}
function progressHTML(o){const value=themeProgress(o.id),current=value==='changes-needed'?1:THEME_STAGES.findIndex(([id])=>id===value);return `<section class="theme-progress" aria-label="${escape(o.name)} theme progress"><div class="progress-heading"><strong>Theme progress</strong><label><span class="sr-only">Update ${escape(o.name)} theme progress</span><select aria-label="Update ${escape(o.name)} theme progress" data-progress="${o.id}">${[...THEME_STAGES,['changes-needed','Changes needed']].map(([id,label])=>`<option value="${id}" ${id==='ready'&&!hasTheme(state,o.id)?'disabled':''} ${value===id?'selected':''}>${label}</option>`).join('')}</select></label></div><ol class="progress-timeline">${THEME_STAGES.map(([id,label],i)=>`<li class="${i<current?'complete':i===current?'current':'upcoming'}" ${i===current?'aria-current="step"':''}><span class="progress-dot" aria-hidden="true">${i<current?'✓':i+1}</span><span>${label}</span></li>`).join('')}</ol>${value==='changes-needed'?'<p class="progress-note">Changes needed. Back in progress before another review.</p>':''}</section>`}
function occasionDialog(){return `<dialog class="copy-dialog" id="occasion-dialog" aria-labelledby="occasion-dialog-title"><h2 id="occasion-dialog-title">Add occasion</h2><form id="occasion-form"><label for="occasion-name">Occasion name</label><input id="occasion-name" maxlength="60" required autocomplete="off"><p id="occasion-error" role="alert"></p><div class="actions">${btn('Cancel','cancel-occasion')}<button class="button primary" type="submit">Save occasion</button></div></form></dialog>`}
let managingId=null;
function renderLibrary(){const removed=allOccasions(state).filter(o=>o.removed);return `<div class="section-heading"><div><h2>Your occasions</h2><p>Only themes marked Ready to use can go live. Saved dates stay separate.</p></div>${btn('Add occasion','add-occasion','primary small')}</div><div class="occasion-grid">${sortedOccasionSummaries(state,at()).map(summary=>{const {definition:o,campaign:c,active,manual,start,end,repeat,status,detail,more,kind,showDates}=summary;return `<article class="occasion-item" aria-label="${escape(o.name)}"><div class="occasion-summary">${btn(occasionIcon(o.id),'change-icon','occasion-symbol',`data-occasion="${o.id}" aria-label="Change ${escape(o.name)} icon" title="Change icon"`)}<div><h3>${escape(o.name)}</h3>${labelsHTML(c)}</div></div><div class="occasion-actions">${btn('Edit','edit','small',`data-id="${c.id}" aria-label="Edit ${escape(o.name)}"`)}${btn('Rename','rename-occasion','small',`data-occasion="${o.id}" aria-label="Rename ${escape(o.name)}"`)}${btn('Remove','remove-occasion','small quiet',`data-occasion="${o.id}" aria-label="Remove ${escape(o.name)}"`)}<label class="checkbox-small"><input type="checkbox" data-activate="${c.id}" ${active?'checked':''} ${isThemeReady(state,o.id)?'':'disabled'}> Turn on now</label></div>${!showDates?`<details class="draft-dates"><summary>${validRange(c)?'Saved dates and schedule settings':'No dates set · Schedule settings'}</summary>`:''}<div class="occasion-dates"><span><strong>${!showDates?'Saved start':manual?'Activated':'Starts'}</strong> ${formatDate(start)}</span><span><strong>Ends</strong> ${end?formatDate(end):manual?'When switched off':'No end date set'}</span><span class="occasion-repeat">${repeat}</span>${btn('Edit schedule','edit-schedule','schedule-link',`data-id="${c.id}" aria-label="Edit ${escape(o.name)} schedule"`)}${more.length?`<details class="more-schedules"><summary>${more.length} more ${more.length===1?'schedule':'schedules'}</summary><ul>${more.map(other=>`<li><span>${formatDate(other.start)} to ${formatDate(other.end)} · Schedule: ${campaignLabels(state,other,at()).schedule} · Theme: ${campaignLabels(state,other,at()).theme}</span>${btn('Edit schedule','edit-schedule','schedule-link',`data-id="${other.id}" aria-label="Edit ${escape(o.name)} ${yearOf(other.start)} schedule"`)}</li>`).join('')}</ul></details>`:''}</div>${!showDates?'</details>':''}${progressHTML(o)}</article>`}).join('')||'<p>No occasions yet. Add one to start planning.</p>'}</div>${removed.length?`<details class="removed-occasions"><summary>Removed occasions (${removed.length})</summary><p>Restore an occasion with its saved work. Its schedules stay off until you enable them again.</p>${removed.map(o=>`<div><span>${escape(o.name)}</span>${btn('Restore','restore-occasion','small',`data-occasion="${o.id}" aria-label="Restore ${escape(o.name)}"`)}</div>`).join('')}</details>`:''}${occasionDialog()}${iconDialog()}${removalDialog()}${readyDialog()}${activationDialog()}`}




let activationPending=null;
function activationDialog(){return `<dialog class="copy-dialog ready-dialog" id="activation-dialog" aria-labelledby="activation-title" aria-describedby="activation-context activation-replaces activation-duration activation-note"><h2 id="activation-title">Turn on theme now?</h2><p id="activation-context"></p><h3 id="activation-replaces"></h3><p id="activation-duration"></p><p id="activation-note"></p><p id="activation-updated" role="status"></p><p class="hint">Live change. Saved schedule dates stay unchanged.</p><div class="actions">${btn('Cancel','cancel-activation')}${btn('Confirm turn on','confirm-activation','primary','id="confirm-activation"')}</div></dialog>`}
function showActivationConfirmation(id,updated=false){const outcome=manualActivationConfirmation({...state,clock:{simulated:false}},id,nowSAST());activationPending={id,outcome};$('activation-title').textContent='Turn on '+outcome.name+' now?';$('activation-context').textContent=outcome.previewAt?'Preview date: '+formatDate(outcome.previewAt)+'. This changes the local date preview.':'This switches the website immediately.';$('activation-replaces').textContent='Replaces '+outcome.replaces;$('activation-duration').textContent=outcome.allowed?'Stays active until you turn it off or choose Resume schedule.':outcome.reason;$('activation-note').textContent=outcome.allowed?'It will not stop at the saved end date. Automatic schedules will not take over until you resume them.':'Nothing will activate until the theme has artwork and is Ready to use.';$('activation-updated').textContent=updated?'The current theme or settings changed. Please check these details again.':'';$('confirm-activation').disabled=!outcome.allowed;if(!$('activation-dialog').open)$('activation-dialog').showModal();$('activation-dialog').querySelector('[data-action=cancel-activation]').focus()}
function focusActivation(id){document.querySelector('[data-activate="'+id+'"]')?.focus()}
function cancelActivation(){const id=activationPending?.id;activationPending=null;render();if(id)focusActivation(id)}
$('app').addEventListener('cancel',e=>{if(e.target.id==='activation-dialog'){e.preventDefault();cancelActivation()}},true);

let readyPending=null;
function readyDialog(){return `<dialog class="copy-dialog ready-dialog" id="ready-dialog" aria-labelledby="ready-title" aria-describedby="ready-context ready-outcome ready-detail"><h2 id="ready-title">Mark theme Ready to use?</h2><p id="ready-context"></p><h3 id="ready-outcome"></h3><p id="ready-detail"></p><p id="ready-updated" role="status"></p><p class="hint">This updates the live settings. Your saved dates stay unchanged.</p><div class="actions">${btn('Cancel','cancel-ready')}${btn('Confirm Ready to use','confirm-ready','primary')}</div></dialog>`}
function showReadyConfirmation(oid,updated=false){const outcome=readyConfirmation({...state,clock:{simulated:false}},oid,nowSAST());readyPending={oid,outcome};$('ready-title').textContent='Mark '+outcome.name+' Ready to use?';$('ready-context').textContent=outcome.previewAt?'Preview date: '+formatDate(outcome.previewAt)+'. The result below uses this pretend date.':'Based on the current date and saved schedule.';$('ready-outcome').textContent=outcome.kind==='immediate'?(outcome.previewAt?'Activates immediately in this preview':'Activates immediately'):outcome.kind==='scheduled'?'Will go live on '+formatDate(outcome.start):'Will stay off';$('ready-detail').textContent=outcome.kind==='off'?outcome.reason:outcome.kind==='immediate'?'Confirming makes this theme visible now'+(outcome.end?', until '+formatDate(outcome.end)+'.':', until you turn it off.'):'It will start automatically and end on '+formatDate(outcome.end)+'.';$('ready-updated').textContent=updated?'The timing or settings changed. Please check the updated result before confirming.':'';if(!$('ready-dialog').open)$('ready-dialog').showModal();$('ready-dialog').querySelector('[data-action=cancel-ready]').focus()}
function focusProgress(oid){document.querySelector('[data-progress="'+oid+'"]')?.nextElementSibling?.querySelector('[role=combobox]')?.focus()}
function cancelReady(){const oid=readyPending?.oid;readyPending=null;render();if(oid)focusProgress(oid)}
$('app').addEventListener('cancel',e=>{if(e.target.id==='ready-dialog'){e.preventDefault();cancelReady()}},true);

let removingId=null;
function removalDialog(){return `<dialog class="copy-dialog" id="remove-dialog" aria-labelledby="remove-title"><h2 id="remove-title">Remove occasion?</h2><p id="remove-explanation"></p><p>Its schedules will stop. Saved work can be restored from Removed occasions.</p><div class="actions">${btn('Keep occasion','cancel-remove')}${btn('Yes, remove occasion','confirm-remove','primary')}</div></dialog>`}

function renderHistory(){return `<div class="section-heading"><div><h2>Change history</h2><p>Saved changes, with who changed what and when.</p></div></div><ol class="history-list">${state.history.map(h=>`<li><time>${formatDate(h.at)}</time><div><p>${escape(h.action)}</p><small>${escape(h.actor)}</small></div></li>`).join('')}</ol>`}
function copyFields(){return Object.entries({eyebrow:'Introductory line',headline:'Main headline',body:'Supporting sentence',button:'Button label'}).map(([key,label])=>`<div class="field"><div class="label-line"><label for="copy-${key}">${label}</label><button class="reset" data-action="reset-copy-field" data-key="${key}">Use original</button></div>${['headline','body'].includes(key)?`<textarea id="copy-${key}" data-copy="${key}" placeholder="${escape(ORIGINAL_COPY[key])}">${escape(draft.copy[key])}</textarea>`:`<input id="copy-${key}" data-copy="${key}" value="${escape(draft.copy[key])}" placeholder="${escape(ORIGINAL_COPY[key])}">`}</div>`).join('')}
function appearancePanel(){const o=occasion(draft.occasion);return `<h2>${escape(o.name)} appearance</h2><p>One design across every campaign for this occasion.</p>${hasTheme(state,o.id)?`<div class="design-thumb"><img src="/admin-concept-christmas.png" alt="Provisional Christmas design"></div><div class="mini-palette"><i style="background:${o.bg}"></i><i style="background:${o.ink}"></i><i style="background:${o.color}"></i></div>${check('decorations','Seasonal decorations','Show the occasion’s decorative artwork.',draft.decorations)}${check('motion','Allow gentle motion','Visitors can pause it. Reduced motion takes priority.',draft.motion)}<p class="note">The occasion button in the visitor navbar turns this campaign off or on.</p>`:'<p class="plain-note">No theme has been created yet. The draft shows the original website until a design is added. You can plan dates and save wording in advance.</p>'}`}

const ruleSelect=(id,label,options,value)=>`<label class="field"><span class="label-line">${label}</span><select id="${id}" aria-label="${label}">${options.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${l}</option>`).join('')}</select></label>`;
function ruleControls(){const r=draft.dateRule;if(!r)return '';return `<div class="date-rule-controls">${ruleSelect('rule-kind','Occasion falls on',[['weekday','Weekday of a month'],['date','Day and month'],['easter','Easter Sunday']],r.kind)}<div class="rule-grid">${r.kind==='weekday'?ruleSelect('rule-ordinal','Which week',ORDINALS,r.ordinal)+ruleSelect('rule-weekday','Day of the week',WEEKDAYS.map((x,i)=>[i,x]),r.weekday):''}${r.kind!=='easter'?ruleSelect('rule-month','Month',MONTHS.map((x,i)=>[i+1,x]),r.month):''}${r.kind==='date'?`<label class="field"><span class="label-line">Day of the month</span><input id="rule-day" type="number" min="1" max="31" value="${r.day}"></label>`:''}</div><label class="field"><span class="label-line">${draft.repeat==='annual'?'First occasion year':'Occasion year'}</span><input id="rule-year" type="number" min="2026" max="2100" value="${r.year}"></label><div class="rule-grid"><label class="field"><span class="label-line">Start days before</span><input id="rule-before" type="number" min="0" max="365" value="${-r.startDays}"></label><label class="field"><span class="label-line">Start time</span><input id="rule-start-time" type="time" value="${r.startTime}"></label><label class="field"><span class="label-line">End days after</span><input id="rule-after" type="number" min="0" max="365" value="${r.endDays}"></label><label class="field"><span class="label-line">End time</span><input id="rule-end-time" type="time" value="${r.endTime}"></label></div><p class="hint">Use 0 for the occasion itself. An end time of 00:00 stops at the start of that day.</p><p id="date-rule-summary" class="rule-summary" aria-live="polite"></p></div>`}
function updateRuleDates(){if(!draft.dateRule)return;const dates=ruleDates(draft.dateRule);draft.start=dates?.start||'';draft.end=dates?.end||'';draft.datesReviewed=!!dates;if($('start'))$('start').value=draft.start;if($('end'))$('end').value=draft.end;const r=draft.dateRule,next=ruleDates(r,r.year+1);if($('date-rule-summary'))$('date-rule-summary').textContent=dates?`${ruleLabel(r)} · ${new Date(dates.occasionDate+'T12:00:00+02:00').toLocaleDateString('en-ZA',{day:'numeric',month:'short',year:'numeric',timeZone:'Africa/Johannesburg'})}. Starts ${-r.startDays} ${r.startDays===-1?'day':'days'} before, ends ${r.endDays} ${r.endDays===1?'day':'days'} after.${draft.repeat==='annual'&&next?' Next year: '+formatDate(next.start)+' to '+formatDate(next.end)+'.':''}`:'Complete the rule to calculate valid dates.'}
function refreshScheduleControls(){const scroll=$('schedule-panel').scrollTop;$('schedule-panel').innerHTML=schedulePanel();enhanceSelects($('schedule-panel'));updateRuleDates();$('schedule-panel').scrollTop=scroll;changed()}
function schedulePanel(){const o=occasion(draft.occasion),following=!!draft.dateRule,days=validRange(draft)?Number(((millis(draft.end)-millis(draft.start))/86400000).toFixed(3)):'';return `<h2>Choose its moment</h2><p>Save dates now. They only activate when the schedule is enabled and the theme is Ready to use.</p>${check('enabled','Enable schedule','Keep this off while planning. Saving dates never switches it on.',draft.enabled)}${ruleSelect('date-mode','Set dates using',[['fixed','Fixed dates'],['occasion','Follow the occasion']],following?'occasion':'fixed')}${ruleControls()}<div class="calculated-dates">${following?'<h3>Calculated dates</h3><p class="hint">These fields follow the rule above.</p>':''}<label class="field"><span class="label-line">Starts</span><input id="start" type="datetime-local" value="${draft.start}" ${following?'readonly':''}></label><label class="field"><span class="label-line">Ends</span><input id="end" type="datetime-local" value="${draft.end}" ${following?'readonly':''}></label></div>${following?'':`<label class="field"><span class="label-line">Duration in days</span><input type="number" min="0.001" step="any" id="duration" value="${days}"></label><p class="hint">Change the end or duration. The other updates automatically.</p>`}${ruleSelect('repeat','Repeat',[['none','One time only'],['annual','Every year']],draft.repeat)}${following?'<p class="hint">Every year recalculates the occasion and its dates. It does not enable the schedule.</p>':o.moving?check('datesReviewed','I have reviewed these dates','Use Follow the occasion for dates that recalculate every year.',draft.datesReviewed):'<p class="hint">Fixed dates repeat on the same dates and times each year.</p>'}${o.id==='birthday'&&!draft.start?'<p class="hint">Choose your anniversary date. No birthday date has been assumed.</p>':''}<div id="schedule-error" class="error" role="alert"></div><p class="summary" id="schedule-summary"></p><p class="hint">To activate immediately, use Turn on now in Occasions and confirm the change.</p>`}
function editorHTML(){const o=occasion(draft.occasion),editions=state.campaigns.filter(c=>c.occasion===draft.occasion);return `<button class="breadcrumb" data-action="view" data-view="library">‹ All occasions</button><div class="page-heading editor-heading"><div><div class="title-line"><h1>${escape(o.name)}</h1><span class="badge">${statusOf(state.campaigns.find(c=>c.id===selectedId),state,at()).toUpperCase()}</span></div><p class="intro">Your theme, wording and schedule. Preview before applying.</p></div><div class="actions"><span class="save-status" id="save-state">${editorDrafts.isUnsaved(selectedId)?'Unsaved changes':state.drafts[selectedId]?'Saved draft':'Current settings'}</span>${btn('Discard','discard')}${btn('Save draft','save-draft')}${btn('Apply changes','publish','primary','id="apply-demo"')}</div></div>${clockBar()}<div class="edition-row"><label for="edition">Campaign</label><select id="edition" class="edition-select">${editions.map(c=>`<option value="${c.id}" ${c.id===selectedId?'selected':''}>${c.start?formatDate(c.start):'No dates set'} · ${statusOf(c,state,at())}</option>`).join('')}</select>${validRange(draft)?btn('Copy to another year','copy-year','small'):''}<span class="fields-note">Same occasion, same theme.</span></div><div class="editor"><div class="controls"><div class="tabs" role="tablist" aria-label="Theme settings">${['appearance','wording','schedule'].map(t=>`<button id="${t}-tab" role="tab" tabindex="${tab===t?0:-1}" data-action="tab" data-tab="${t}" aria-selected="${tab===t}" aria-controls="${t}-panel">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><div class="tab-content" id="${tab}-panel" role="tabpanel" tabindex="0" aria-labelledby="${tab}-tab">${tab==='wording'?`<h2>A few seasonal words</h2><p>Changes appear immediately in This draft, even before a theme is created. Leave a field blank to use the normal website wording.</p>${copyFields()}<button class="text-link" data-action="reset-all-copy">Use original wording for all fields</button><p class="note">Button destination and product prices stay connected to the existing store.</p>`:tab==='appearance'?appearancePanel():schedulePanel()}</div></div><section class="preview"><div class="preview-tools"><strong>Live preview</strong><div class="preview-controls"><select id="preview-page" aria-label="Preview page">${[['/','Homepage'],['/collections','Collections'],['/studio','Photo studio'],['/basket','Basket'],['/contact','Contact']].map(([v,l])=>`<option value="${v}" ${page===v?'selected':''}>${l}</option>`).join('')}</select><div class="segmented"><button data-action="device" data-device="desktop" aria-pressed="${device==='desktop'}">Desktop</button><button data-action="device" data-device="mobile" aria-pressed="${device==='mobile'}">Mobile</button></div></div></div><div class="preview-mode"><label for="preview-mode">Show</label><select id="preview-mode"><option value="draft" ${previewMode==='draft'?'selected':''}>This draft</option><option value="schedule" ${previewMode==='schedule'?'selected':''}>Website at selected date</option></select><span id="preview-reason"></span></div><div class="canvas"><div class="browser-frame ${device==='mobile'?'mobile':''}" id="browser-frame"><div class="browser-chrome"><span class="address">CustomVibe · website preview</span></div><div class="view-port" id="view-port"><iframe id="site-preview" src="/preview?page=${encodeURIComponent(page)}" title="Seasonal visitor preview"></iframe></div></div><div class="preview-foot"><span>Try the visitor’s occasion button and preferences.</span><button class="text-link" data-action="reset-visitor">Reset visitor choices</button></div></div></section></div><p class="plain-note">Save draft keeps live settings unchanged. Apply changes updates the saved settings and schedule.</p><dialog class="copy-dialog" id="copy-dialog"><h2>Reuse this campaign</h2><p>Creates a new draft for the same occasion. Nothing activates automatically.</p><label for="copy-year-input">Year</label><input id="copy-year-input" type="number" min="2026" max="2100" value="${draft.start?yearOf(draft.start)+1:new Date().getFullYear()+1}"><p id="copy-error" role="alert"></p><div class="actions">${btn('Cancel','cancel-copy')}${btn('Create draft','confirm-copy','primary')}</div></dialog>`}
function render(){const focusTab=document.activeElement?.getAttribute('role')==='tab';const focusLabel=document.activeElement?.getAttribute('role')==='combobox'?document.activeElement.getAttribute('aria-label'):null;frameObserver?.disconnect();$('app').innerHTML=view==='editor'?editorHTML():shell(view==='calendar'?renderCalendar():view==='library'?renderLibrary():view==='history'?renderHistory():renderOverview());enhanceSelects($('app'));if(focusTab)$('app').querySelector('[role=tab][aria-selected=true]')?.focus({preventScroll:true});if(focusLabel)[...$('app').querySelectorAll('[role=combobox]')].find(el=>el.getAttribute('aria-label')===focusLabel)?.focus({preventScroll:true});if(view==='editor'){const frame=$('site-preview');frame.onload=postPreview;frameObserver=new ResizeObserver(resizeFrame);frameObserver.observe($('view-port'));resizeFrame();updateRuleDates();updateValidation()} }
function openEditor(id){selectedId=id;const current=state.drafts[id]||state.campaigns.find(c=>c.id===id);draft=editorDrafts.open(id,{...current,manualSelected:false,manualType:state.override?.until?'date':'forever',manualUntil:state.override?.until||current.end});view='editor';render();window.scrollTo(0,0)}
function resizeFrame(){if(!$('site-preview'))return;const w=$('view-port').clientWidth,target=device==='mobile'?390:1280,scale=w/target;Object.assign($('site-preview').style,{width:target+'px',height:($('view-port').clientHeight/scale)+'px',transform:`scale(${scale})`})}
function postPreview(){const frame=$('site-preview');if(!frame)return;const resolved=activeInfo(),c=previewCampaign(state,previewMode==='draft'?{...draft,key:draft.id+':'+yearOf(draft.start)}:resolved.campaign,{draft:previewMode==='draft'});frame.contentWindow.postMessage({type:'cv-season-preview',previewMode,campaign:c,definition:c?occasion(c.occasion):null,at:at(),embedded:true},location.origin);if($('preview-reason'))$('preview-reason').textContent=previewMode==='draft'?(hasTheme(state,draft.occasion)?'Draft appearance and wording':'Draft wording · original website design'):(resolved.campaign&&!hasTheme(state,resolved.campaign.occasion)?'No theme yet · original website':resolved.reason+(resolved.campaign?'':' · saved wording stays off'))}
function updateValidation(){const error=validatePublish(state,draft);const until=draft.manualType==='forever'?null:draft.manualType==='date'?draft.manualUntil:draft.end;const manualError=draft.manualSelected&&readinessIssue(state,draft.occasion)|| (draft.manualSelected&&until&&(!Number.isFinite(millis(until))||millis(until)<=millis(at()))?'Manual end must be after the current time.':'');if($('schedule-error'))$('schedule-error').textContent=error||manualError;if($('schedule-summary'))$('schedule-summary').textContent=validRange(draft)?`${draft.enabled?(isThemeReady(state,draft.occasion)?'When applied:':'Saved dates only. '+readinessIssue(state,draft.occasion)):'Schedule off:'} ${formatDate(draft.start)} to ${formatDate(draft.end)}.`:'';$('apply-demo').disabled=!!(error||manualError)}
function changed(){editorDrafts.update(selectedId,draft);if($('save-state'))$('save-state').textContent=editorDrafts.isUnsaved(selectedId)?'Unsaved changes':state.drafts[selectedId]?'Saved draft':'Current settings';updateValidation();postPreview()}
function setClock(value){if(!Number.isFinite(millis(value))){notify('Choose a valid preview date.');return}state.clock={simulated:true,at:value};if(view==='editor'){render()}else render()}
async function activateCampaign(id){const c=state.campaigns.find(c=>c.id===id);if(!c||!isThemeReady(state,c.occasion)){render();notify(c?readinessIssue(state,c.occasion):'Choose an occasion.');return}state.mode='manual';state.override={id,from:nowSAST(),until:null};await persist('Confirmed manual activation of '+occasion(c.occasion).name+' until turned off or the automatic schedule is resumed.');render();notify(occasion(c.occasion).name+' is now active.')}
$('app').addEventListener('keydown',e=>{
 if(busy||!loaded||e.target.getAttribute('role')!=='tab'||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;
 e.preventDefault();const tabs=['appearance','wording','schedule'],index=tabs.indexOf(tab);
 tab=e.key==='Home'?tabs[0]:e.key==='End'?tabs.at(-1):tabs[(index+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length];render();
});
$('app').addEventListener('click',e=>perform(async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
 if(action==='add-occasion'||action==='rename-occasion'){managingId=b.dataset.occasion||null;$('occasion-dialog-title').textContent=managingId?'Rename occasion':'Add occasion';$('occasion-name').value=managingId?occasion(managingId).name:'';$('occasion-error').textContent='';$('occasion-dialog').showModal();$('occasion-name').focus()}
 else if(action==='change-icon'){iconId=b.dataset.occasion;iconChoice=structuredClone(occasion(iconId).customIcon||null);iconBusy=false;iconLoad++;$('icon-title').textContent='Change '+occasion(iconId).name+' icon';$('icon-error').textContent='';$('icon-file').value='';refreshIconChoice();$('icon-dialog').showModal()}
 else if(action==='choose-icon'||action==='reset-icon'){iconLoad++;iconBusy=false;iconChoice=action==='reset-icon'?null:{preset:b.dataset.icon};$('icon-error').textContent='';refreshIconChoice()}
 else if(action==='cancel-icon'){iconLoad++;$('icon-dialog').close()}
 else if(action==='save-icon'){if(iconBusy)return;try{saveIcon(state,iconId,iconChoice);await persist('Updated '+occasion(iconId).name+' icon across its card and calendar.');render();notify('Icon saved. Calendar updated.')}catch(error){$('icon-error').textContent='Could not save this icon. Please try again or choose a preset icon.'}}
 else if(action==='cancel-occasion')$('occasion-dialog').close();
 else if(action==='remove-occasion'){removingId=b.dataset.occasion;$('remove-title').textContent='Remove '+occasion(removingId).name+'?';$('remove-explanation').textContent='Are you sure you want to remove this occasion?';$('remove-dialog').showModal();$('remove-dialog').querySelector('[data-action=cancel-remove]').focus()}
 else if(action==='cancel-activation'){cancelActivation()}
 else if(action==='confirm-activation'){if(!activationPending)return;const {id,outcome}=activationPending;await refreshRemote();const latest=manualActivationConfirmation({...state,clock:{simulated:false}},id,nowSAST());if(!latest.allowed||JSON.stringify(latest)!==JSON.stringify(outcome)){showActivationConfirmation(id,true);return}activationPending=null;await activateCampaign(id);focusActivation(id)}
 else if(action==='cancel-ready'){cancelReady()}
 else if(action==='confirm-ready'){if(!readyPending)return;const {oid,outcome}=readyPending;await refreshRemote();if(!visibleOccasions(state).some(o=>o.id===oid)){readyPending=null;render();notify('This occasion was removed. Nothing was approved.');return}const latest=readyConfirmation({...state,clock:{simulated:false}},oid,nowSAST());if(JSON.stringify(latest)!==JSON.stringify(outcome)){showReadyConfirmation(oid,true);return}setThemeProgress(state,oid,'ready');readyPending=null;await persist('Confirmed '+occasion(oid).name+' Ready to use. '+(latest.kind==='immediate'?'Activates immediately'+(latest.previewAt?' in the date preview.':'.'):latest.kind==='scheduled'?'Will go live on '+formatDate(latest.start)+'.':'Stays off. '+latest.reason));render();focusProgress(oid);notify('Ready to use confirmed.')}
 else if(action==='cancel-remove'){$('remove-dialog').close();removingId=null}
 else if(action==='confirm-remove'){if(!removingId)return;const id=removingId,name=occasion(id).name;removeOccasion(state,id);removingId=null;await persist('Removed '+name+' after confirmation. Schedules stopped; saved work can be restored.');for(const c of state.campaigns.filter(c=>c.occasion===id))editorDrafts.saved(c.id);render();notify(name+' removed. Restore it under Removed occasions.')}

 else if(action==='restore-occasion'){const id=b.dataset.occasion;restoreOccasion(state,id);await persist('Restored '+occasion(id).name+'. Schedules remain off.');render();notify('Occasion restored. Enable its schedule when ready.')}
 else if(action==='view'){await persist();view=b.dataset.view;render();window.scrollTo(0,0)}
 else if(action==='edit')openEditor(b.dataset.id);
 else if(action==='edit-schedule'){tab='schedule';openEditor(b.dataset.id)}
 else if(action==='tab'){tab=b.dataset.tab;render()}
 else if(action==='device'){device=b.dataset.device;render()}
 else if(action==='apply-clock')setClock($('clock-at').value);
 else if(action==='real-clock'){state.clock={simulated:false,at:nowSAST()};await persist();render()}
 else if(action.startsWith('jump-')){const oid=action.slice(5),c=preferred(oid);month=c.start.slice(0,7);selectedDay=c.start.slice(0,10);setClock(localTime(millis(c.start)+3600000))}
 else if(action==='previous-year'||action==='next-year'){const y=Number(month.slice(0,4))+(action==='next-year'?1:-1);if(y>=2026&&y<=2100){month=y+'-01';selectedDay='';render()}}
 else if(action==='show-year'){const y=Number($('calendar-year').value);if(Number.isInteger(y)&&y>=2026&&y<=2100){month=y+'-01';selectedDay='';render()}else notify('Choose a year from 2026 to 2100.')}
 else if(action==='day'){selectedDay=b.dataset.date;setClock(selectedDay+'T12:00')}
 else if(action==='stop'){state.mode='off';state.override=null;await persist('Stopped all seasonal themes. Original stays on until Resume schedule.');render();notify('Original appearance is on. Schedules are paused.')}
 else if(action==='resume'){state.mode='schedule';state.override=null;await persist('Resumed the automatic schedule.');render();notify('Schedule resumed.')}
 else if(action==='visitor-date')window.open('/preview?at='+encodeURIComponent(at()),'_blank','noopener');
 else if(action==='visitor')window.open('https://customvibe.co.za/','_blank','noopener');
 else if(action==='reset-visitor'){localStorage.removeItem(PREF_KEY);await persist('Reset local visitor preferences.');$('site-preview')?.contentWindow.postMessage({type:'cv-season-reset'},location.origin);notify('Visitor preferences reset.');postPreview()}
 else if(action==='reset-copy-field'){draft.copy[b.dataset.key]='';render();changed()}
 else if(action==='reset-all-copy'){Object.keys(ORIGINAL_COPY).forEach(k=>draft.copy[k]='');render();changed()}
 else if(action==='save-draft'){state.drafts[selectedId]=structuredClone(draft);await persist('Saved a draft for '+occasion(draft.occasion).name+'. Live settings unchanged.');editorDrafts.saved(selectedId);editorDrafts.open(selectedId,draft);$('save-state').textContent='Draft saved';notify('Draft saved. The live settings are unchanged.')}
 else if(action==='discard'){if(!confirm('Discard the saved draft and unsaved changes?'))return;delete state.drafts[selectedId];await persist('Discarded saved draft.');editorDrafts.saved(selectedId);openEditor(selectedId);notify('Restored the applied settings.')}
 else if(action==='publish'){const error=validatePublish(state,draft);if(error){tab='schedule';render();notify(error);return}updateValidation();if($('apply-demo').disabled)return;const next=structuredClone(draft);delete next.manualSelected;delete next.manualType;delete next.manualUntil;next.published=true;state.campaigns=state.campaigns.map(c=>c.id===selectedId?next:c);delete state.drafts[selectedId];if(draft.manualSelected){state.mode='manual';state.override={id:selectedId,from:nowSAST(),until:draft.manualType==='forever'?null:draft.manualType==='date'?draft.manualUntil:draft.end}}await persist('Applied '+occasion(draft.occasion).name+' settings'+(draft.manualSelected?' and activated a manual override.':next.enabled?' with its schedule.':' with scheduling off.'));editorDrafts.saved(selectedId);editorDrafts.open(selectedId,draft);render();notify('Changes saved.')}
 else if(action==='copy-year')$('copy-dialog').showModal();
 else if(action==='cancel-copy')$('copy-dialog').close();
 else if(action==='confirm-copy'){const year=Number($('copy-year-input').value);if(!Number.isInteger(year)||year<2026||year>2100){$('copy-error').textContent='Choose a year from 2026 to 2100.';return}try{const c=cloneCampaign(draft,year);state.campaigns.push(c);await persist('Copied '+occasion(c.occasion).name+' to a new '+year+' draft'+(occasion(c.occasion).moving?'; date review required.':'.'));openEditor(c.id);tab='schedule';render()}catch(error){$('copy-error').textContent=error.message}}

},e));
$('app').addEventListener('submit',e=>perform(async e=>{if(e.target.id!=='occasion-form')return;e.preventDefault();try{const name=$('occasion-name').value;saveOccasion(state,managingId,name);await persist((managingId?'Renamed occasion to ':'Added occasion ')+name.trim()+'.');render();notify('Occasion saved.')}catch(error){$('occasion-error').textContent=error.message;$('occasion-name').focus()}},e));
$('app').addEventListener('input',e=>{const el=e.target,id=el.id;if(el.dataset.copy){draft.copy[el.dataset.copy]=el.value;changed();return}if(!draft||view!=='editor')return;if(id.startsWith('rule-')&&draft.dateRule){const fields={'rule-year':'year','rule-day':'day','rule-before':'startDays','rule-after':'endDays','rule-start-time':'startTime','rule-end-time':'endTime'},key=fields[id];if(key){draft.dateRule[key]=id.includes('time')?el.value:el.value===''?null:Number(el.value)*(id==='rule-before'?-1:1);updateRuleDates();changed();return}}if(['start','end','manual-until'].includes(id)){draft[id==='manual-until'?'manualUntil':id]=el.value;if(id!=='manual-until'&&validRange(draft)&&$('duration'))$('duration').value=Number(((millis(draft.end)-millis(draft.start))/86400000).toFixed(3));changed()}if(id==='duration'){const n=Number(el.value);if(n>0&&Number.isFinite(millis(draft.start))){draft.end=localTime(millis(draft.start)+n*86400000);$('end').value=draft.end;changed()}}});
$('app').addEventListener('change',e=>perform(async e=>{const el=e.target,id=el.id;if(id==='icon-file'){const request=++iconLoad;iconBusy=true;$('icon-error').textContent='Preparing icon…';refreshIconChoice();try{const choice=await prepareIcon(el.files[0]);if(request!==iconLoad)return;iconChoice=choice;$('icon-error').textContent='Image ready. Save to apply it.'}catch(error){if(request!==iconLoad)return;$('icon-error').textContent=error.message}finally{if(request===iconLoad){iconBusy=false;refreshIconChoice()}}return}if(el.dataset.progress){const oid=el.dataset.progress,value=el.value;if(!visibleOccasions(state).some(o=>o.id===oid)||![...THEME_STAGES.map(([id])=>id),'changes-needed'].includes(value))return;if(value==='ready'&&themeProgress(oid)!=='ready'){await refreshRemote();render();showReadyConfirmation(oid);return}setThemeProgress(state,oid,value);await persist('Updated '+occasion(oid).name+' theme progress to '+el.options[el.selectedIndex].text+'. Saved dates unchanged. '+(isThemeReady(state,oid)?'Eligible for enabled schedules.':'Activation blocked until Ready to use and artwork exists.'));render();document.querySelector('[data-progress="'+oid+'"]')?.focus();notify(isThemeReady(state,oid)?'Ready to use. Enabled schedules can now activate this theme.':'Progress saved. Activation is blocked; saved dates are unchanged.');return}if(el.dataset.activate){if(el.checked){const cid=el.dataset.activate;await refreshRemote();render();showActivationConfirmation(cid)}else{state.mode='off';state.override=null;await persist('Turned off the active theme. Resume schedule to restart automatic themes.');render()}return}if(id==='calendar-year'){const y=Number(el.value);if(Number.isInteger(y)&&y>=2026&&y<=2100){month=y+'-01';selectedDay='';render()}else{el.value=month.slice(0,4);notify('Choose a year from 2026 to 2100.')}}else if(id==='show-drafts'){showDrafts=el.checked;render()}else if(id==='edition')openEditor(el.value);else if(id==='preview-page'){page=el.value;render()}else if(id==='preview-mode'){previewMode=el.value;postPreview()}else if(view==='editor'){if(id==='date-mode'){if(el.value==='fixed'){delete draft.dateRule;if(occasion(draft.occasion).moving)draft.repeat='none'}else{draft.dateRule=occasionRule(draft.occasion,yearOf(draft.start))||{kind:'date',year:yearOf(draft.start),month:Number(draft.start?.slice(5,7))||1,day:Number(draft.start?.slice(8,10))||1,startDays:-14,endDays:1,startTime:'08:00',endTime:'00:00'};updateRuleDates()}refreshScheduleControls();return}if(['rule-kind','rule-month','rule-ordinal','rule-weekday'].includes(id)){const key=id.slice(5);draft.dateRule[key]=key==='kind'?el.value:Number(el.value);if(key==='kind'){draft.dateRule.month??=6;draft.dateRule.day??=1;draft.dateRule.ordinal??=3;draft.dateRule.weekday??=0}updateRuleDates();refreshScheduleControls();return}if(['enabled','decorations','motion','datesReviewed'].includes(id))draft[id]=el.checked;else if(id==='repeat'){draft.repeat=el.value;updateRuleDates();refreshScheduleControls();return}else if(id==='activate'){draft.manualSelected=el.checked;$('manual-fields').hidden=!el.checked}else if(id==='manual-type'){draft.manualType=el.value;$('custom-until-field').hidden=el.value!=='date'}changed()}},e));
window.addEventListener('beforeunload',e=>{if(editorDrafts.hasUnsaved()){e.preventDefault();e.returnValue=''}});
window.addEventListener('message',e=>{if(e.origin===location.origin&&e.data?.type==='cv-season-ready')postPreview()});
setInterval(async()=>{if(busy||view==='editor'||document.querySelector('dialog[open],details[open],[role=combobox][aria-expanded=true]'))return;try{await refreshRemote();render()}catch{$('connection-status').textContent='Connection lost. Keep this tab open and check sign-in above.'}},60000);
try{await refreshRemote();loaded=true;$('connection-status').textContent='Saved';render()}catch(error){$('connection-status').textContent=error.message;$('app').innerHTML='<p>Settings could not load. Reload to try again.</p>'}

window.addEventListener('cv-admin-session-restored',async()=>{if(loaded)return;try{await refreshRemote();loaded=true;$('connection-status').textContent='Saved';render()}catch(error){$('connection-status').textContent=error.message}});
